import sys
import requests
import os

def main():
    if len(sys.argv) != 3:
        print("Usage: python quote_client.py <url> <token_file>", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    token_file = sys.argv[2]

    try:
        with open(token_file, 'r') as f:
            token = f.read().strip()
    except Exception as e:
        print(f"Error reading token file: {e}", file=sys.stderr)
        sys.exit(1)

    headers = {'Authorization': f'Bearer {token}'}

    try:
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            body = response.text
            print(body)
            with open('last_quote.txt', 'w') as f:
                f.write(body)
        else:
            print(response.status_code, file=sys.stderr)
            sys.exit(1)
    except requests.RequestException:
        if os.path.exists('last_quote.txt'):
            with open('last_quote.txt', 'r') as f:
                print(f.read())
        else:
            print("no cached quote", file=sys.stderr)
            sys.exit(1)

if __name__ == '__main__':
    main()
